INSERT OR REPLACE INTO "char_abilities" VALUES(1031001500,3,2025501,'(系列条件)额外行动增加 LV1','[{"tid":202550101,"trait_id":202550101,"trait":{"id":202550101,"trait_type":19,"trait_value":1,"desc":"搭乘单位含有「机动战士高达 雷霆战线」系列时，\n「额外行动」+1次","action_timing":0,"tlimit":0,"active_condition_set_id":1000094,"target_condition_set_id":1000001,"value_source_condition_set_id":0,"target_weapon_condition_id":0,"use_battle_animation":false,"battle_power_value_rate_percent":5,"trait_boost_condition_set_id":0,"active_condition":{"id":1000094,"trait_condition_set_id":1000094,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"310","unit_size":"","tension":"","standby_terrain":"","weapon_attribute":"","weapon_attack_attribute":"","map_battle_action":"","hp_type":0,"hp_rate_lte_threshold":0,"hp_rate_gte_threshold":0,"en_rate_lte_threshold":0,"en_rate_gte_threshold":0,"en_value_lte_threshold":0,"en_value_gte_threshold":0,"use_hp_rate_lte_threshold":false,"attack_distance_gte_threshold":0,"attack_distance_lte_threshold":0,"turn_number":0,"is_in_chance_step":false,"is_in_one_on_one":false,"unit_ids":"","character_ids":"","character_tags_id":"","character_series_id":"","tags":null,"series":{"id":310,"world_id":1,"name":"机动战士高达 雷霆战线","desc":"宇宙世纪0079年。\n自地球联邦军与自护公国之间爆发战争开始，已快经过一年的时间。\nSIDE4的宇宙殖民卫星群姆亚在自护军的攻击下惨遭破坏，许多人因而丧生。\n殖民卫星与战舰的残骸犹如亡灵一般漂流在宙域中，\n姆亚就此化为了危险的暗礁宙域。\n残骸互相碰撞、带电，激发出永无止尽的闪电。\n不知何时起，这片宙域便被世人以不知是谁起的俗名称呼。\n也就是「雷霆宙域」。","icon":"series_0310","sort":3500,"schedule_id":2507109901,"scenario_stage_series_id":320,"scenario":null,"scenarios":null,"scenario_stages":null},"character_series":null,"character_tags":null},"target_condition":{"id":1000001,"trait_condition_set_id":1000001,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"","unit_size":"","tension":"","standby_terrain":"","weapon_attribute":"","weapon_attack_attribute":"","map_battle_action":"","hp_type":0,"hp_rate_lte_threshold":0,"hp_rate_gte_threshold":0,"en_rate_lte_threshold":0,"en_rate_gte_