INSERT OR REPLACE INTO "char_abilities" VALUES(1055001500,3,2012702,'契合度：机动战士Gundam GQuuuuuuX LV2','[{"tid":201270200,"trait_id":201270201,"trait":{"id":201270201,"trait_type":17,"trait_value":10,"desc":"搭乘单位含有「机动战士Gundam GQuuuuuuX」系列时，\n对敌方造成的损伤提升10%、\n自身受到的损伤减轻10%","action_timing":0,"tlimit":0,"active_condition_set_id":1000223,"target_condition_set_id":1000001,"value_source_condition_set_id":0,"target_weapon_condition_id":0,"use_battle_animation":false,"battle_power_value_rate_percent":5,"trait_boost_condition_set_id":0,"active_condition":{"id":1000223,"trait_condition_set_id":1000223,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"550","unit_size":"","tension":"","standby_terrain":"","weapon_attribute":"","weapon_attack_attribute":"","map_battle_action":"","hp_type":0,"hp_rate_lte_threshold":0,"hp_rate_gte_threshold":0,"en_rate_lte_threshold":0,"en_rate_gte_threshold":0,"en_value_lte_threshold":0,"en_value_gte_threshold":0,"use_hp_rate_lte_threshold":false,"attack_distance_gte_threshold":0,"attack_distance_lte_threshold":0,"turn_number":0,"is_in_chance_step":false,"is_in_one_on_one":false,"unit_ids":"","character_ids":"","character_tags_id":"","character_series_id":"","tags":null,"series":{"id":550,"world_id":1,"name":"机动战士Gundam GQuuuuuuX","desc":"天手让叶是名女高中生，在空中的宇宙殖民地过著平静的生活。但在遇到难民少女娜安后，她被卷入了非法机动战士决斗竞技《军团战》之中。\n她化名《玛秋》参赛，驾驶著GQuuuuuuX，每日投身激烈的战斗。\n同时，被宇宙军队和警察两方追捕的神秘机动战士《高达》及其驾驶员──少年修治，出现在她们面前。\n接著，世界迎向了新时代。","icon":"series_0550","sort":5600,"schedule_id":0,"scenario_stage_series_id":0,"scenario":null,"scenarios":null,"scenario_stages":null},"character_series":null,"character_tags":null},"target_condition":{"id":1000001,"trait_condition_set_id":1000001,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"","unit_size":"","tension":"","standby_terrain":"","weapon_attribute":"","weapon_attack_attribute":"","map_battle_action":"","hp_type":0,"hp_rate_lte_threshold":0,"hp_rate_gte_threshold":0,"en_rate_lte_threshold":0